import { duration } from '@absoluteui/core';
import { DurationPicker } from '@absoluteui/components/duration-picker';

const host = document.createElement('div');
document.body.append(host);
const estimate = DurationPicker.create(host, {
  label: 'Estimate',
  name: 'estimate',
  required: true,
  min: duration(15 * 60_000),
  max: duration(8 * 3_600_000),
  step: duration(15 * 60_000),
});
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(estimate.validity.valid);
});

import { durationToString, parseDuration } from '@absoluteui/core';
import { DurationPicker, type DurationPickerChangeDetail } from '@absoluteui/components/duration-picker';

const host = document.createElement('div');
document.body.append(host);
DurationPicker.create(host, {
  label: 'Lap time',
  fields: ['minutes', 'seconds'],
  value: parseDuration('PT1M30S'),
  validate: (value) => (value !== null && value.milliseconds === 0 ? 'Enter a lap time above zero.' : null),
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<DurationPickerChangeDetail>).detail;
  host.dataset.lap = value ? durationToString(value) : '';
});
